sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	var util = new EquipmentRequestUtil();
	var equipment = util.getEquipmentInfo(current.getValue('equipment'));

	// 1. Validation: equipment must exist and be orderable
    if (!equipment || !equipment.active) {
        gs.addErrorMessage(gs.getMessage('Selected equipment is not available for ordering.'));
        current.setAbortAction(true);
        return;
    }

	var qty = parseInt(current.getValue('quantity'), 10);
    if (isNaN(qty) || qty < 1 || qty > 10) {
        gs.addErrorMessage(gs.getMessage('Quantity must be between 1 and 10.'));
        current.setAbortAction(true);
        return;
    }

	// 2. Derived fields
    var total = equipment.unit_cost * qty;
    current.setValue('total_cost', `USD;${total}`);
    var tier = util.getApprovalTier(total);
    current.setValue('approval_tier', tier);

	// 3. Initial routing, only when the request is brand new
    if (current.operation() === 'insert' || current.getValue('state') === util.STATE.NEW) {
        current.setValue('state',
            tier === util.TIER.AUTO ? util.STATE.APPROVED : util.STATE.PENDING_APPROVAL);
    }

	// 4. Keep the Task "active" flag honest for our custom closed states
    var closedStates = [util.STATE.DELIVERED, util.STATE.REJECTED, util.STATE.CANCELLED];
    current.setValue('active', closedStates.indexOf(current.getValue('state')) === -1);

})(current, previous);
